import{at as e,n as t,rt as n,yt as r}from"./chunks/framework.ne95vkW4.js";var i=JSON.parse(`{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"about/changelog.md","filePath":"about/changelog.md","lastUpdated":1792561504000}`),a={name:`about/changelog.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><p>The previous version of this page was a 20-line template that predated essentially all of the functionality below. This reconstruction groups the project&#39;s <code>git log --oneline --merges origin/main</code> history by theme rather than listing every commit; PR numbers (<code>#NN</code>) link to <code>https://github.com/vaam-store/image-resizer/pull/NN</code>.</p><p><code>emgr</code> doesn&#39;t cut dated, tagged releases yet - <code>Cargo.toml</code>&#39;s <code>version</code> has stayed <code>0.1.2</code> throughout everything below, and <code>.github/workflows/build.yml</code> has no release-tag trigger: every published Docker image is either a floating <code>&lt;flavor&gt;-latest</code> or a per-commit <code>&lt;flavor&gt;-&lt;sha&gt;</code> (see <a href="./../deployment/docker">Docker deployment</a>). Once real, tagged releases start, this file should switch to genuine dated version headings per <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>; until then, everything below is &quot;Unreleased&quot; in that format&#39;s sense.</p><h2 id="⚠️-breaking-changes-for-existing-deployments" tabindex="-1">⚠️ Breaking changes for existing deployments <a class="header-anchor" href="#⚠️-breaking-changes-for-existing-deployments" aria-label="Permalink to “⚠️ Breaking changes for existing deployments”">​</a></h2><ul><li><strong>Signed URLs are on by default</strong> (<a href="https://github.com/vaam-store/image-resizer/issues/27" target="_blank" rel="noreferrer">#27</a>). A deployment that previously ran without <code>SIGNING_KEY</code>/<code>SIGNING_SALT</code> now refuses to start. Set both (hex-encoded), or set <code>ALLOW_UNSIGNED_REQUESTS=true</code> to keep the old, unsigned behavior.</li><li><strong><code>/metrics</code> now requires authentication on <code>otel</code> builds</strong> (<a href="https://github.com/vaam-store/image-resizer/issues/77" target="_blank" rel="noreferrer">#77</a>). A deployment scraping <code>/metrics</code> without configuring <code>METRICS_AUTH_TOKEN</code> now refuses to start. Set it and point Prometheus&#39;s scrape config at it via its <code>authorization</code> block, or set <code>ALLOW_UNAUTHENTICATED_METRICS=true</code>.</li><li><strong>OpenAPI code generation is gone</strong> (<a href="https://github.com/vaam-store/image-resizer/issues/53" target="_blank" rel="noreferrer">#53</a>). <code>openapi.yaml</code> and the generated <code>packages/gen-server</code> crate no longer exist - the HTTP router is hand-written. The wire API is unchanged, but any tooling that depended on the generated crate or the spec file needs updating. <code>make init</code>, the codegen bootstrap that used to be a prerequisite for a fresh clone, is gone with it.</li><li><strong>Resize types honour imgproxy&#39;s real semantics instead of always cropping</strong> (<a href="https://github.com/vaam-store/image-resizer/issues/59" target="_blank" rel="noreferrer">#59</a>, <a href="https://github.com/vaam-store/image-resizer/issues/1" target="_blank" rel="noreferrer">#1</a>). A request using a resize type other than <code>fill</code> now gets a different result than before.</li></ul><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h2><ul><li>SSRF-guarded source fetching: scheme validation, private/loopback/ link-local IP-range blocking (each with an explicit opt-in), a source allowlist (<code>ALLOWED_SOURCES</code>), and re-validation on every redirect hop - not just the original URL (<a href="https://github.com/vaam-store/image-resizer/issues/21" target="_blank" rel="noreferrer">#21</a>).</li><li><code>ALLOWED_SOURCES</code> fixed to actually authorise the private origins it lists, instead of being silently overridden by the private-range guard (<a href="https://github.com/vaam-store/image-resizer/issues/57" target="_blank" rel="noreferrer">#57</a>).</li><li>HMAC-SHA256 signed URLs, imgproxy-compatible, on by default (<a href="https://github.com/vaam-store/image-resizer/issues/27" target="_blank" rel="noreferrer">#27</a>).</li><li>Cache-key validation shared by every storage backend, closing an arbitrary-file-read via an unvalidated key (traversal, absolute paths, percent-decoded forms) - see <code>tests/storage_key_validation.rs</code> (<a href="https://github.com/vaam-store/image-resizer/issues/23" target="_blank" rel="noreferrer">#23</a>).</li><li>Resolution and output-size limits (<code>MAX_SRC_RESOLUTION_MP</code>, <code>MAX_OUTPUT_WIDTH</code>/<code>MAX_OUTPUT_HEIGHT</code>, <code>MAX_ANIMATION_FRAMES</code>) - guards against decode bombs and many-tiny-frame animation bombs (<a href="https://github.com/vaam-store/image-resizer/issues/26" target="_blank" rel="noreferrer">#26</a>).</li><li><code>/metrics</code> bearer-token authentication, fail-closed at startup on <code>otel</code> builds, mirroring the signed-URL check (<a href="https://github.com/vaam-store/image-resizer/issues/77" target="_blank" rel="noreferrer">#77</a>).</li><li><code>cargo-deny</code> wired into CI: RUSTSEC advisory scanning, license checks, duplicate/banned-crate checks, source-registry restriction (epic <a href="https://github.com/vaam-store/image-resizer/issues/9" target="_blank" rel="noreferrer">#9</a>).</li><li>Alpha-channel compositing and transparent-pixel normalization fixed for target formats without alpha support (<a href="https://github.com/vaam-store/image-resizer/issues/34" target="_blank" rel="noreferrer">#34</a>, <a href="https://github.com/vaam-store/image-resizer/issues/60" target="_blank" rel="noreferrer">#60</a>).</li><li>Base container images (Rust builder, distroless runtime) pinned by digest rather than a floating tag (<a href="https://github.com/vaam-store/image-resizer/issues/48" target="_blank" rel="noreferrer">#48</a>).</li></ul><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to “Performance”">​</a></h2><ul><li>SIMD image resampling via <code>fast_image_resize</code>, replacing the <code>image</code> crate&#39;s scalar resampler (<code>#63</code> stage 1).</li><li>DCT-scaled JPEG decode via mozjpeg/libjpeg-turbo: decodes close to the requested output size directly, instead of decoding full-size and downsampling afterward (<code>#63</code> stage 2).</li><li>Full-size JPEG decode also routed through mozjpeg - measured ~1.5x faster than the <code>image</code> crate&#39;s own decoder even without DCT scaling (<a href="https://github.com/vaam-store/image-resizer/issues/67" target="_blank" rel="noreferrer">#67</a>).</li><li>JPEG encoding cut over to mozjpeg/libjpeg-turbo&#39;s <code>Compress</code>, replacing the <code>image</code> crate&#39;s baseline encoder, alongside progressive-JPEG and chroma-subsampling controls (<a href="https://github.com/vaam-store/image-resizer/issues/76" target="_blank" rel="noreferrer">#76</a>).</li><li>CPU-bound image processing moved onto <code>tokio::spawn_blocking</code>, keeping the async runtime responsive under load; a configurable performance profile system (<code>PERFORMANCE_PROFILE</code>: high-throughput / low-latency / memory-efficient) and concurrency limits (epic <a href="https://github.com/vaam-store/image-resizer/issues/9" target="_blank" rel="noreferrer">#9</a>).</li><li>Cgroup-aware CPU-count detection for Tokio worker-thread and concurrency sizing, instead of trusting the host&#39;s full core count from inside a resource-limited container (<a href="https://github.com/vaam-store/image-resizer/issues/44" target="_blank" rel="noreferrer">#44</a>).</li><li>A criterion micro-benchmark suite (<code>benches/</code>) plus a three-way end-to-end harness against imgproxy (<code>bench-imgproxy/</code>), wired into a CI regression gate with a 15% threshold and a PR comment report (<a href="https://github.com/vaam-store/image-resizer/issues/20" target="_blank" rel="noreferrer">#20</a>).</li><li>Every C or C++ dependency removed from the build: <code>mozjpeg</code> (JPEG decode+encode), the <code>webp</code> crate/libwebp (WebP), <code>libavif</code>/AOM/dav1d (AVIF), and <code>mimalloc</code> were replaced by pure-Rust equivalents (<code>jpeg-decoder</code>/<code>jpeg-encoder</code>, <code>vaam-image-webp</code>, <code>ravif</code>/<code>avif-decode</code>, the platform allocator) — see <a href="https://github.com/vaam-apps/image-resizer/blob/main/PERFORMANCE_OPTIMIZATIONS.md" target="_blank" rel="noreferrer">Performance notes</a> (<a href="https://github.com/vaam-store/image-resizer/issues/120" target="_blank" rel="noreferrer">#134</a>). The figures recorded above for <code>#63</code>/<code>#67</code>/<code>#76</code> describe the mozjpeg-era implementation and have not been re-measured against the new codecs.</li></ul><h2 id="formats-and-processing-options" tabindex="-1">Formats and processing options <a class="header-anchor" href="#formats-and-processing-options" aria-label="Permalink to “Formats and processing options”">​</a></h2><ul><li>Lossy and lossless WebP output, plus AVIF output (<a href="https://github.com/vaam-store/image-resizer/issues/35" target="_blank" rel="noreferrer">#35</a>, <a href="https://github.com/vaam-store/image-resizer/issues/4" target="_blank" rel="noreferrer">#4</a>, <a href="https://github.com/vaam-store/image-resizer/issues/49" target="_blank" rel="noreferrer">#49</a>).</li><li>Animated GIF/WebP output, with a configurable frame-count cap (<a href="https://github.com/vaam-store/image-resizer/issues/49" target="_blank" rel="noreferrer">#49</a>).</li><li>EXIF auto-orientation applied and ICC colour profiles forwarded to the output (<a href="https://github.com/vaam-store/image-resizer/issues/33" target="_blank" rel="noreferrer">#33</a>, <a href="https://github.com/vaam-store/image-resizer/issues/5" target="_blank" rel="noreferrer">#5</a>).</li><li>Per-format quality control (<a href="https://github.com/vaam-store/image-resizer/issues/35" target="_blank" rel="noreferrer">#35</a>).</li><li>Progressive JPEG and chroma-subsampling toggles, plus a <code>max_bytes</code> output-size cap (<a href="https://github.com/vaam-store/image-resizer/issues/76" target="_blank" rel="noreferrer">#76</a>).</li><li>imgproxy-compatible resize types (<code>fill</code>, <code>fit</code>, and the rest) instead of always cropping regardless of the requested type (<a href="https://github.com/vaam-store/image-resizer/issues/59" target="_blank" rel="noreferrer">#59</a>).</li><li>Gravity, crop and geometry options; watermarks; named presets (<code>PRESETS</code>) and a processing-option allowlist (<code>ALLOWED_PROCESSING_OPTIONS</code>) (<a href="https://github.com/vaam-store/image-resizer/issues/49" target="_blank" rel="noreferrer">#49</a>, <a href="https://github.com/vaam-store/image-resizer/issues/50" target="_blank" rel="noreferrer">#50</a>, <a href="https://github.com/vaam-store/image-resizer/issues/51" target="_blank" rel="noreferrer">#51</a>, <a href="https://github.com/vaam-store/image-resizer/issues/52" target="_blank" rel="noreferrer">#52</a>).</li></ul><h2 id="architecture-and-reliability" tabindex="-1">Architecture and reliability <a class="header-anchor" href="#architecture-and-reliability" aria-label="Permalink to “Architecture and reliability”">​</a></h2><ul><li>OpenAPI code generation removed: the HTTP router (<code>src/modules/api</code>, <code>src/modules/router</code>, <code>src/modules/url</code>) is hand-written now, so a fresh clone builds with plain <code>cargo build</code> and no Docker/codegen step (<a href="https://github.com/vaam-store/image-resizer/issues/53" target="_blank" rel="noreferrer">#53</a>).</li><li>Cache lifecycle grew TTL support and reachable stale/evicted states, and local-filesystem writes became atomic (a directory could previously be mistaken for a cache hit, and a partial write could be served) - see <code>tests/storage_local_fs_atomicity.rs</code> (<a href="https://github.com/vaam-store/image-resizer/issues/38" target="_blank" rel="noreferrer">#38</a>, <a href="https://github.com/vaam-store/image-resizer/issues/40" target="_blank" rel="noreferrer">#40</a>).</li><li>Graceful shutdown: SIGTERM/SIGINT drain in-flight requests before exit, and OpenTelemetry providers flush on exit instead of losing buffered telemetry on every restart (<a href="https://github.com/vaam-store/image-resizer/issues/42" target="_blank" rel="noreferrer">#42</a>).</li><li>Docker images are now actually run-tested in CI before being pushed, after the <code>s3</code>/<code>s3_otel</code> images shipped completely unable to start for a period (a glibc mismatch between the Rust builder and the distroless runtime - see <a href="./../deployment/docker#the-builderruntime-base-image-pin-do-not-bump-casually">Docker deployment</a>) (<a href="https://github.com/vaam-store/image-resizer/issues/62" target="_blank" rel="noreferrer">#62</a>).</li></ul><h2 id="tooling-and-ci" tabindex="-1">Tooling and CI <a class="header-anchor" href="#tooling-and-ci" aria-label="Permalink to “Tooling and CI”">​</a></h2><ul><li>A real CI pipeline: a per-feature-set test matrix (<code>local_fs</code>, <code>s3</code>, <code>local_fs,otel</code>), Clippy, <code>cargo-deny</code>, and the benchmark regression gate above - previously only a Docker build and a linter ran at all (epic <a href="https://github.com/vaam-store/image-resizer/issues/9" target="_blank" rel="noreferrer">#9</a>, <a href="https://github.com/vaam-store/image-resizer/issues/46" target="_blank" rel="noreferrer">#46</a>).</li><li>A docs/env-var drift check (<code>.github/scripts/check_env_docs.py</code>) fails CI if <code>src/modules/env/env.rs</code> and <a href="./../getting-started/configuration">Configuration</a> disagree in either direction (<a href="https://github.com/vaam-store/image-resizer/issues/47" target="_blank" rel="noreferrer">#47</a>).</li><li>A <code>no-native-deps</code> CI job fails the build if any dependency reintroduces native (C/C++) code, and the Docker build and CI no longer install <code>nasm</code>, <code>cmake</code>, <code>meson</code>, or <code>ninja-build</code> (<a href="https://github.com/vaam-store/image-resizer/issues/120" target="_blank" rel="noreferrer">#134</a>).</li><li>A Knative Serverless Helm chart (<code>helm/serverless/</code>) added alongside the Deployment-based chart (<code>helm/emgr/</code>), for scale-to-zero setups.</li><li>A <code>PodDisruptionBudget</code> and liveness/readiness/startup probes added to the Deployment Helm chart - previously a voluntary disruption could evict every replica at once, and a wedged container was never restarted (<a href="https://github.com/vaam-store/image-resizer/issues/48" target="_blank" rel="noreferrer">#48</a>).</li><li>ADRs recording the image-engine choice, the URL/API shape, and measurement writeups for the WebP and AVIF encoder decisions (<code>adr/0001</code> through <code>adr/0005</code>). Note <code>adr/0004</code> is <strong>superseded</strong> by <code>adr/0005</code>, which re-measured AVIF against the encoders actually shipped (libavif/AOM and mozjpeg) after both sides of <code>0004</code>&#39;s comparison were replaced; <code>0004</code> is kept for the record, with its numbers marked void.</li></ul>`,15)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};